claim_compilation_result.query:
(
    df.filter(
        prompt("The {dialog} contains a customer complaint")
    )
    .map(
        prompt(
            "Identify whether the {dialog} contains a customer complaint regarding flight delays",
            bool
        ).alias("about_flight_delays")
    )
    .aggregate(
        [proportion(col("about_flight_delays")).alias("delay_prop")],
        group_by=[col("company_id")]
    )
    .aggregate(
        [count_if(col("delay_prop") > 0.15).alias("num_companies_with_high_delay_complaints")]
    )
    .check(col("num_companies_with_high_delay_complaints").eq(4))
)
